# Teste manual v9.1 (Revit fechado durante a instalacao):
# 1. Selecionar original 8K. Campo de objetos vazio ou malformado deve impedir envio a API.
# 2. Identificar objetos reais: cozinha, ao lado da bancada => geladeira inox, duas portas.
# 3. Materiais opcionais: local => acabamento; conferir prompt antes de gerar.
# 4. Gerar UMA vez, Alta/2560x1280. Comparar objeto, materiais, contornos e emenda em 360.
# 5. Salvar: referencia.png 4096x2048; render.png 2560x1280; generation.json com dimensoes/objetos, sem chave.
# 6. Reabrir generation.json; referencia maior deve carregar. Geracoes antigas tambem devem abrir.
# 7. Conferir reparo opcional de emenda e Print. Captura/projecao/viewer nao alterados.
# Validacao realizada: checks C# independentes compilados por Roslyn .NET 8 e executados com sucesso;
# HTTP simulado, nenhuma chamada paga. Build WPF/Revit e teste visual pendentes no Windows.
[CmdletBinding()]
param(
    [string]$ProjectRoot,
    [string]$RevitRoot,
    [switch]$OnlyUpdateSources
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

# Arqyzeng Panorama v9.1 - atualizacao sobre a base v9.0.2 corrigida; referencia independente e objetos localizados.
# Modifica somente os oito arquivos listados, com backup e verificacao da base.
# O fluxo scripts/dev.ps1 continua sendo responsavel por checks/build/instalacao.
if ([string]::IsNullOrWhiteSpace($ProjectRoot)) {
    $currentRoot = (Get-Location).Path
    if (Test-Path -LiteralPath (Join-Path $currentRoot 'src\Arqyzeng.Revit\PanoramaCaptureService.cs')) {
        $ProjectRoot = $currentRoot
    }
    elseif (Test-Path -LiteralPath (Join-Path $PSScriptRoot 'src\Arqyzeng.Revit\PanoramaCaptureService.cs')) {
        $ProjectRoot = $PSScriptRoot
    }
    else { throw 'Execute na raiz do projeto ou informe -ProjectRoot com o caminho da copia atual.' }
}
$ProjectRoot = [IO.Path]::GetFullPath($ProjectRoot)
$devScript = Join-Path $ProjectRoot 'scripts\dev.ps1'
if (-not (Test-Path -LiteralPath $devScript -PathType Leaf)) {
    throw 'scripts/dev.ps1 ausente. Esta atualizacao exige a nova infraestrutura; nao use o instalador legado.'
}
function Get-SourceHash([string]$Path) {
    $text = [IO.File]::ReadAllText($Path).Replace("`r`n", "`n").TrimStart([char]0xFEFF)
    $algorithm = [Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [Text.Encoding]::UTF8.GetBytes($text)
        return [BitConverter]::ToString($algorithm.ComputeHash($bytes)).Replace('-', '')
    }
    finally { $algorithm.Dispose() }
}
if ((Get-SourceHash $devScript) -ne '8A02CE1C4F9A6C864C3F1E6BCFB06F3D7529969527F0007769E6FA1FE71394CB') {
    throw 'scripts/dev.ps1 difere da base enviada. Nenhum fonte foi alterado. Envie a versao atual para adaptar a atualizacao.'
}
if (-not $OnlyUpdateSources -and (Get-Process -Name Revit -ErrorAction SilentlyContinue)) {
    throw 'Feche o Revit antes de atualizar e instalar.'
}
$changes = @(
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\PrintWindow.cs'; BaseHash = '9A5710A8CEDEBE1A621C9474993A7FDD4079610235E764468BA5B856C24B597C'; NewHash = '4DDF4F22AAA21326F5E068803F16F458B675034FEFA5C281C4E2B71707CADE01'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\PrintWindow.PanoramaAi.cs'; BaseHash = '9D362157642437FF9754B20F882D7D3F0044B768C2ED7DF093DA2DD13AB0BF6A'; NewHash = '8626CB1C779FB2022AC3980C5227B123C4EB7AB65CAC1D417FDABC0398FAD342'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\PrintWindow.PanoramaSeam.cs'; BaseHash = 'E76B93AC62005F4816043D3DA65F05298D917B098E4DD2CA04B7619C71B46A40'; NewHash = '0995A19B850D0C8E32522359C4A5CF7ECABFBE098D49A4B8B0AB131E540AE74E'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\PanoramaSeamMath.cs'; BaseHash = 'B9C31DE962ADB6EC33932F3DB247EB9CB93B0F2E7CE4A9153F4D4BDE50B2CDFE'; NewHash = '9D521D12C922A51BBC27A2E7AAAC1EF608CCBD30D7DFAE87122D366B97AFD378'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\PanoramaRenderContract.cs'; BaseHash = 'F566E9DE7A1D3C9552B598A646E7D9D0F5CE2A28C938B94B2E94E4069F736B21'; NewHash = '55FB57896FB6F1DC1D76254B865D554506AA45875D22B0C57A287D718CADC5E6'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\OpenAiImageProvider.cs'; BaseHash = 'E6B6B351C47CDC5F50135CAF27C106E0732A90FD10A9D6635DDC23ED345632C2'; NewHash = 'E9504E16B8CC59F09870967914A64BDA868336A53C706005F36C8B54802A719D'; Payload = '' },
    [pscustomobject]@{ Relative = 'src\Arqyzeng.Revit\ImageProviderChecks.cs'; BaseHash = '30C55E9268B47D367F5C089D6C36F8653A3D974309CED98087F00B24073A043C'; NewHash = 'C9EDFFDA2C6D9258FE0499DC84CB1AC5534CF4C656AF629F4B42535A78FE48C4'; Payload = '' },
    [pscustomobject]@{ Relative = 'tests\Arqyzeng.Rendering.Checks\Program.cs'; BaseHash = '2FBCDC93D41B31E2FD3BD47488DF8BFBF3AE42CC06BDC79520250BF31A8553BD'; NewHash = 'F1745950DE86762E7C0E596BE3A7C85B572A8C1DF24056EF5F4D0819539382FE'; Payload = '' }
)
# Validar TODOS os arquivos antes de escrever qualquer um.
foreach ($change in $changes) {
    $path = Join-Path $ProjectRoot $change.Relative
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        if ($change.BaseHash -eq 'MISSING') { continue }
        throw "Fonte ausente: $path. Nenhum fonte foi alterado."
    }
    $hash = Get-SourceHash $path
    if ($hash -ne $change.BaseHash -and $hash -ne $change.NewHash) {
        throw "O arquivo $($change.Relative) possui alteracoes diferentes da base enviada. Nenhum fonte foi alterado. Preserve seu trabalho e envie a versao atual."
    }
}
$pending = @($changes | Where-Object {
    $sourcePath = Join-Path $ProjectRoot $_.Relative
    (-not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) -or ((Get-SourceHash $sourcePath) -ne $_.NewHash)
})
$backupDir = $null
if ($pending.Count -gt 0) {
    $backupId = (Get-Date -Format 'yyyyMMdd_HHmmss') + '_' + [guid]::NewGuid().ToString('N').Substring(0, 8)
    $backupDir = Join-Path $ProjectRoot ('.artifacts\update-backups\panorama-9.1-' + $backupId)
    New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
    foreach ($change in $pending) {
        $backupPath = Join-Path $backupDir $change.Relative
        New-Item -ItemType Directory -Path ([IO.Path]::GetDirectoryName($backupPath)) -Force | Out-Null
        if (Test-Path -LiteralPath (Join-Path $ProjectRoot $change.Relative)) {
            Copy-Item -LiteralPath (Join-Path $ProjectRoot $change.Relative) -Destination $backupPath
        }
    }
}
try {
    foreach ($change in $pending) {
        $path = Join-Path $ProjectRoot $change.Relative
        [IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($change.Payload))
        if ((Get-SourceHash $path) -ne $change.NewHash) { throw "Falha ao conferir o fonte atualizado: $($change.Relative)" }
    }
    Write-Host "Fontes Panorama v9.1 preparados em: $ProjectRoot"
    if ($backupDir) { Write-Host "Backup dos fontes: $backupDir" }
    if ($OnlyUpdateSources) {
        Write-Host 'Somente fontes atualizados. Plugin instalado permanece na versao anterior. Revise o diff no Git antes de publicar.'
    }
    else {
        Push-Location $ProjectRoot
        try {
            $arguments = @('-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $devScript, '-Action', 'Install')
            if (-not [string]::IsNullOrWhiteSpace($RevitRoot)) { $arguments += @('-RevitRoot', $RevitRoot) }
            & powershell.exe @arguments
            if ($LASTEXITCODE -ne 0) { throw "Checks/build/instalacao falharam (codigo $LASTEXITCODE)." }
        }
        finally { Pop-Location }
        Write-Host 'Panorama v9.1 instalado. Referencia ate 4096x2048, render 2560x1280 Alta por padrao. Identifique objetos importantes por local antes de gerar; confira prompt, cores, geometria e fechamento. API paga, sem repeticao automatica.'
    }
}
catch {
    $updateError = $_
    if ($backupDir) {
        foreach ($change in $pending) {
            $backupPath = Join-Path $backupDir $change.Relative
            $sourcePath = Join-Path $ProjectRoot $change.Relative
            if (Test-Path -LiteralPath $backupPath -PathType Leaf) {
                Copy-Item -LiteralPath $backupPath -Destination $sourcePath -Force
            }
            elseif (Test-Path -LiteralPath $sourcePath -PathType Leaf) {
                Remove-Item -LiteralPath $sourcePath -Force
            }
        }
        throw "Atualizacao interrompida; fontes anteriores restaurados. Confira a mensagem de instalacao e o backup $backupDir. Causa: $updateError"
    }
    throw $updateError
}
